const D:usize=8;const L:usize=26;
unsafe fn put64(o:*mut u8,x:i64){let b=x as u64;for j in 0..8{*o.add(j)=(b>>(8*j)) as u8;}}
#[no_mangle]pub unsafe extern "C" fn concave_gap_alignment_global(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<5||length>L{return -1}let nr=*input;let mr=*input.add(1);if nr<1||nr>D as i64||mr<1||mr>D as i64{return -1}let n=nr as usize;let m=mr as usize;let g=n.max(m);if length!=2+n+m+g{return -1}let mut x=[0i64;D];let mut y=[0i64;D];let mut w=[0i64;D];let mut p=2;for i in 0..n{x[i]=*input.add(p);p+=1;if x[i]<0||x[i]>3{return -1}}for j in 0..m{y[j]=*input.add(p);p+=1;if y[j]<0||y[j]>3{return -1}}let mut slope=i64::MAX;for k in 0..g{w[k]=*input.add(p);p+=1;if w[k]<0||w[k]>100{return -1}let prev=if k>0{w[k-1]}else{0};let d=w[k]-prev;if k>0&&(w[k]<w[k-1]||d>slope){return -1}slope=d}if output.is_null()||capacity<8{return -2}let mut dp=[[i64::MAX/4;D+1];D+1];dp[0][0]=0;for i in 0..=n{for j in 0..=m{if i==0&&j==0{continue}let mut best=i64::MAX/4;if i>0&&j>0{let mismatch=if x[i-1]!=y[j-1]{1}else{0};best=best.min(dp[i-1][j-1]+mismatch)}for z in 1..=i{best=best.min(dp[i-z][j]+w[z-1])}for z in 1..=j{best=best.min(dp[i][j-z]+w[z-1])}dp[i][j]=best}}put64(output,dp[n][m]);8}
